// capacity-estimate.ts
const PEAK_FACTOR = 5 // x5 peak factor -- never explained where this multiplier came from
const THRESHOLD_QPS = 1000 // the single magic threshold the whole architecture call hinges on
const RETENTION_YEARS = 10

interface TrafficInputs {
  dailyActiveUsers: number
  requestsPerUserPerDay: number
  avgRecordSizeBytes: number
}

interface CapacityEstimate {
  peakQps: number
  recommendation: 'distributed store' | 'single relational node'
  storageBytes: number
}

function estimateCapacity(inputs: TrafficInputs): CapacityEstimate {
  const { dailyActiveUsers, requestsPerUserPerDay, avgRecordSizeBytes } = inputs

  const averageQps = (dailyActiveUsers * requestsPerUserPerDay) / 86400 // seconds/day
  const peakQps = averageQps * PEAK_FACTOR

  // ONE global decision branch -- the core defect: peakQps is only ever
  // compared against the bare constant THRESHOLD_QPS, never against any
  // component's actual measured capacity (a relational node's real ceiling
  // is roughly 1-5K write QPS; a cache node's is far higher).
  const recommendation: CapacityEstimate['recommendation'] =
    peakQps > THRESHOLD_QPS ? 'distributed store' : 'single relational node'

  // Incomplete: no replicationFactor multiplier (e.g. x3) and no
  // indexOverhead factor, so this understates the real 10-year footprint.
  const storageBytes =
    dailyActiveUsers * requestsPerUserPerDay * avgRecordSizeBytes * 365 * RETENTION_YEARS

  return { peakQps, recommendation, storageBytes }
}

// Example run cited in the PR description:
const result = estimateCapacity({
  dailyActiveUsers: 926_640,
  requestsPerUserPerDay: 40,
  avgRecordSizeBytes: 500,
})
// -> peakQps = 2145, recommendation = 'distributed store'
console.log(result)
